--This file was generated by AI

-- installer.lua
-- Installs or upgrades to the latest release of this project from GitHub.
--
-- Run it with:
--   wget run https://raw.githubusercontent.com/Sirc23/RASCL/main/install.lua

term.clear()
term.setCursorPos(1,1)

local repo           = "https://github.com/Sirc23/RASCL/"
local branch         = "main"       -- the branch that holds the releases folder
local releasesFolder = "releases"

-- Config files that get edited after the download, relative to the install location
local SERVER_CONFIG = "rascl/tables/server_config.csv"
local CLIENT_CONFIG = "rascl/tables/client_config.csv"

-- The config CSVs use the single byte 0xF7 (the "÷" glyph in ComputerCraft's
-- character set) as their delimiter. It is NOT UTF-8, so every file is
-- downloaded, read and written in binary mode to keep it byte-for-byte intact.
local DELIM = "\247"

local API_HEADERS = {
	["User-Agent"] = "ComputerCraft-Installer",
	["Accept"] = "application/vnd.github+json",
}
local RAW_HEADERS = { ["User-Agent"] = "ComputerCraft-Installer" }

------------------------------------------------------------------------
-- Helpers
------------------------------------------------------------------------

local function trim(s)
	return (s or ""):match("^%s*(.-)%s*$")
end

-- Percent-encodes everything in a path except letters, digits, "-._~" and "/"
local function encodePath(path)
	return (path:gsub("[^%w%-%._~/]", function(c)
		return ("%%%02X"):format(c:byte())
	end))
end

-- GET a URL in binary mode, retrying on transient failures.
-- Returns body, or nil, errorMessage, httpStatusCode
local function httpGet(url, headers)
	local lastErr, code
	for _ = 1, 3 do
		local res, err, failRes = http.get(url, headers, true)
		if res then
			local body = res.readAll() or ""
			res.close()
			return body
		end
		lastErr = err or "unknown error"
		code = nil
		if failRes then
			code = failRes.getResponseCode()
			failRes.close()
		end
		-- A 4xx answer won't change by asking again
		if code and code >= 400 and code < 500 then break end
		sleep(1)
	end
	return nil, lastErr, code
end

-- GET from the GitHub API and decode the JSON reply
local function apiGet(path)
	local body, err, code = httpGet("https://api.github.com/repos/" .. path, API_HEADERS)
	if not body then
		local msg = "GitHub request failed: " .. tostring(err)
		if code == 403 or code == 429 then
			msg = msg .. "\nThis is probably GitHub's rate limit (60 requests per hour per IP"
				.. " address, shared by everyone on this server). Try again later."
		end
		error(msg, 0)
	end
	local data, jsonErr = textutils.unserialiseJSON(body)
	if data == nil then
		error("Could not read GitHub's reply: " .. tostring(jsonErr), 0)
	end
	return data
end

-- Splits "a1.10.3" into a prefix letter ("a") and numbers ({1, 10, 3})
local function parseVersion(name)
	local nums = {}
	for n in name:sub(2):gmatch("%d+") do
		nums[#nums + 1] = tonumber(n)
	end
	return name:sub(1, 1), nums
end

-- Orders versions so the newest sorts last. "a" (alpha) sorts before "v"
-- (release), and the numbers are compared as numbers, so a1.10.0 comes
-- after a1.9.0 (a plain string sort would put it before).
local function versionLess(a, b)
	local prefixA, numsA = parseVersion(a)
	local prefixB, numsB = parseVersion(b)
	if prefixA ~= prefixB then return prefixA < prefixB end
	for i = 1, math.max(#numsA, #numsB) do
		local x, y = numsA[i] or 0, numsB[i] or 0
		if x ~= y then return x < y end
	end
	return a < b
end

-- Returns nil if the hostname is fine, otherwise a sentence explaining why not
local function hostnameProblem(s)
	if #s == 0 then
		return "The hostname can't be empty."
	end
	if #s > 16 then
		return ("The hostname is %d characters long; the maximum is 16."):format(#s)
	end
	local bad = s:gsub("[%w_%-]", "")
	if #bad > 0 then
		local seen, list = {}, {}
		for c in bad:gmatch(".") do
			if not seen[c] then
				seen[c] = true
				list[#list + 1] = (c == " ") and "space" or ("'" .. c .. "'")
			end
		end
		return "The hostname contains characters that aren't allowed: " .. table.concat(list, ", ")
			.. ". Use only letters, numbers, underscores and dashes."
	end
	return nil
end

-- Writes data to path (binary), creating parent folders as needed
local function writeFile(path, data)
	local dir = fs.getDir(path)
	if dir ~= "" and not fs.exists(dir) then
		fs.makeDir(dir)
	end
	local handle, err = fs.open(path, "wb")
	if not handle then
		return false, "Could not write /" .. path .. ": " .. tostring(err)
	end
	handle.write(data)
	handle.close()
	return true
end

-- Sets the value for `key` in a "key<DELIM>value" CSV, leaving every other
-- byte of the file as it was. The row is added if the key isn't there yet.
local function setConfigValue(path, key, value)
	local handle = fs.open(path, "rb")
	if not handle then
		return false, "Could not open /" .. path .. " - is it part of this release?"
	end
	local content = handle.readAll() or ""
	handle.close()

	local lines, found = {}, false
	-- Appending "\n" means a file ending in a newline yields a final "" entry,
	-- so joining with "\n" below reproduces the original ending exactly.
	for line in (content .. "\n"):gmatch("(.-)\n") do
		local cr = line:match("\r$") or ""
		local body = line:sub(1, #line - #cr)
		local rowKey = body:match("^(.-)" .. DELIM)
		if rowKey == key then
			line = key .. DELIM .. value .. cr
			found = true
		end
		lines[#lines + 1] = line
	end

	if not found then
		local newRow = key .. DELIM .. value
		if lines[#lines] == "" then
			table.insert(lines, #lines, newRow)
		else
			lines[#lines + 1] = newRow
		end
	end

	return writeFile(path, table.concat(lines, "\n"))
end

------------------------------------------------------------------------
-- File classification
------------------------------------------------------------------------

-- Paths are relative to the release folder. "startup/" goes in the root of
-- the computer; everything else goes in the install location. An entry that
-- ends in "/" matches everything beneath that folder.

-- Code: always overwritten with the release's copy
local codePaths = {
	"startup/",
	"rascl/classes/",
	"rascl/files.txt",
	"rascl/generic.lua",
	"rascl/LICENSE",
	"rascl/tables/containerTypes.csv",
}

-- Configs: the release's copy, with the user's values kept for keys that still exist
local configPaths = {
	"rascl/tables/server_config.csv",
	"rascl/tables/client_config.csv",
}

-- Anything not listed above is user data: written only if it doesn't exist yet.

-- Each entry applies when upgrading from a version below `version` to a
-- version at or above it.
-- resetOnUpgrade: these files are replaced with the release's copy
local resetOnUpgrade = {
	{ version = "a1.1.0", files = {
		"rascl/tables/recipes.csv",
		"rascl/tables/itemInfo.csv",
		"rascl/tables/tags.csv",
	}},
}

-- deleteOnUpgrade: these files are deleted (unless the release contains them)
local deleteOnUpgrade = {
	{ version = "a1.1.0", files = {
		"rascl/classes/RemotePeripheral.lua",
	}},
}

local function pathMatches(path, list)
	for _, entry in ipairs(list) do
		if entry:sub(-1) == "/" then
			if path:sub(1, #entry) == entry then return true end
		elseif path == entry then
			return true
		end
	end
	return false
end

local function classify(rel)
	if pathMatches(rel, configPaths) then return "config" end
	if pathMatches(rel, codePaths) then return "code" end
	return "data"
end

local function destination(installDir, rel)
	if rel:sub(1, 8) == "startup/" then return rel end
	return fs.combine(installDir, rel)
end

-- Returns a set of every file listed by an entry whose version lies in
-- (installed, target]. Empty on a fresh install (installed == nil).
local function collectFiles(entries, installed, target)
	local set = {}
	if not installed then return set end
	for _, entry in ipairs(entries) do
		if versionLess(installed, entry.version) and not versionLess(target, entry.version) then
			for _, file in ipairs(entry.files) do
				set[file] = true
			end
		end
	end
	return set
end

local function readFile(path)
	local handle = fs.open(path, "rb")
	if not handle then return nil end
	local content = handle.readAll() or ""
	handle.close()
	return content
end

local function splitRows(content)
	local rows = {}
	for line in (content .. "\n"):gmatch("(.-)\n") do
		rows[#rows + 1] = line
	end
	return rows
end

-- Returns the release's config with the user's value for every key the
-- release still has. Keys only the user's file has are dropped.
local function mergeConfig(releaseContent, userContent)
	local userValues = {}
	for _, line in ipairs(splitRows(userContent)) do
		local body = line:gsub("\r$", "")
		local key, value = body:match("^(.-)" .. DELIM .. "(.*)$")
		if key and userValues[key] == nil then
			userValues[key] = value
		end
	end

	local rows = splitRows(releaseContent)
	for i, line in ipairs(rows) do
		local cr = line:match("\r$") or ""
		local body = line:sub(1, #line - #cr)
		local key = body:match("^(.-)" .. DELIM)
		if key and userValues[key] ~= nil then
			rows[i] = key .. DELIM .. userValues[key] .. cr
		end
	end
	return table.concat(rows, "\n")
end

-- Looks for an existing installation. Returns its install directory and
-- installed version (or nil, nil if there is none).
local function findExistingInstall()
	local base = settings.get("rascl")
	if type(base) ~= "string" then return nil end
	base = base:gsub("/+$", "")
	if not base:match("/rascl$") then return nil end
	if not fs.exists(fs.combine(base, "files.txt")) or not fs.exists("startup/rascl.lua") then
		return nil
	end

	local installDir = base:sub(1, #base - 6)
	if installDir == "" then installDir = "/" end

	local version = (readFile("startup/rascl.lua") or ""):match('^%s*version%s*=%s*"([^"]+)"')
	if not (version and version:match("^[av]%d+%.%d+%.%d+$")) then
		print("Could not read the installed version; treating it as the oldest.")
		version = "a0.0.0"
	end
	return installDir, version
end

-- Writes every downloaded file according to its classification.
-- `installed` is nil on a fresh install.
local function applyFiles(installDir, contents, installed, target)
	local resetSet = collectFiles(resetOnUpgrade, installed, target)
	local deleteSet = collectFiles(deleteOnUpgrade, installed, target)

	-- startup/rascl.lua carries the version, so it is written last: an
	-- interrupted upgrade still reads as the old version and can be re-run.
	local stamp = "startup/rascl.lua"
	local order = {}
	for rel in pairs(contents) do
		if rel ~= stamp then order[#order + 1] = rel end
	end
	table.sort(order)

	local function writeOne(rel)
		local dest = destination(installDir, rel)
		local data = contents[rel]
		local existing = nil
		if fs.exists(dest) and not fs.isDir(dest) then
			existing = readFile(dest)
		end

		local kind = classify(rel)
		local ok, err = true, nil
		if resetSet[rel] or kind == "code" or existing == nil then
			ok, err = writeFile(dest, data)
		elseif kind == "config" then
			ok, err = writeFile(dest, mergeConfig(data, existing))
		end
		if not ok then error(err, 0) end
	end

	for _, rel in ipairs(order) do
		writeOne(rel)
	end

	for rel in pairs(deleteSet) do
		local dest = destination(installDir, rel)
		if not contents[rel] and fs.exists(dest) then
			fs.delete(dest)
		end
	end

	if contents[stamp] then
		writeOne(stamp)
	end
end

------------------------------------------------------------------------
-- Prompts
------------------------------------------------------------------------

local function promptInstallDir()
	term.clear()
	term.setCursorPos(1,1)
	print("Step 1: Installation directory")
	print("Please type the installation directory relative to root")
	print("(eg. \"foo/bar\" \26 /foo/bar)")
	while true do
		write("> ")
		local dir = fs.combine("/", trim(read()))
		if dir == ".." or dir:sub(1, 3) == "../" then
			printError("That location is outside this computer's file system.")
		elseif fs.exists(dir) and not fs.isDir(dir) then
			printError("/" .. dir .. " is a file, not a directory.")
		elseif fs.isReadOnly(dir) then
			printError("/" .. dir .. " is read-only.")
		else
			if not settings.get("rascl") then
				settings.define("rascl", {description = "Base directory for rascl", type = "string", default = "/rascl"})
			end
			dir = "/" .. dir
			if dir:sub(-1) == "/" and #dir > 1 then
				dir = dir:gsub(".$", "")
			end
			
			if dir == "/" then
				settings.set("rascl", "/rascl")
				settings.save()
			else
				settings.set("rascl", dir .. "/rascl")
				settings.save()
			end
			return dir
		end
	end
end

local function promptHostname()
	term.clear()
	term.setCursorPos(1,1)
	print("Step 2: Hostname")
	print("Please type a unique hostname, up to 16 characters")
	print("Letters, numbers, _, and - are allowed")
	while true do
		write("> ")
		local hostname = trim(read())
		local problem = hostnameProblem(hostname)
		if not problem then return hostname end
		printError(problem)
	end
end

local function promptDeviceType()
	term.clear()
	term.setCursorPos(1,1)
	print("Step 3: Device Type")
	print("Please specify the device type")
	print("(h)ost, (c)rafter or (r)emote")
	local types = { h = "host", c = "crafter", r = "remote" }
	while true do
		write("> ")
		local choice = trim(read()):lower()
		if types[choice] then return types[choice] end
		printError("Please type h, c or r.")
	end
end

------------------------------------------------------------------------
-- Installer
------------------------------------------------------------------------

local function main()
	if not http then
		error("The HTTP API is disabled, so files can't be downloaded.", 0)
	end

	local owner, name = repo:match("github%.com/([^/]+)/([^/]+)")
	if not owner then
		error("'repo' should look like https://github.com/<user>/<repo_name>/", 0)
	end
	name = name:gsub("%.git$", "")

	-- 1. Where to install (or where the existing installation is)
	local installDir, installed = findExistingInstall()
	local isUpgrade = installed ~= nil
	if isUpgrade then
		print("Found version " .. installed .. " in " .. installDir)
	else
		installDir = promptInstallDir()
		print("Installing to " .. installDir)
	end

	-- 2. Find the latest version
	print("Looking for the latest version...")
	local listing = apiGet(("%s/%s/contents/%s?ref=%s"):format(owner, name, releasesFolder, branch))
	local versions = {}
	for _, entry in ipairs(listing) do
		if entry.type == "dir" and entry.name:match("^[av]%d+%.%d+%.%d+$") then
			versions[#versions + 1] = entry
		end
	end
	if #versions == 0 then
		error("No release folders (named like a1.0.0 or v1.0.0) were found in '"
			.. releasesFolder .. "' on branch '" .. branch .. "'.", 0)
	end
	table.sort(versions, function(a, b) return versionLess(a.name, b.name) end)
	local latest = versions[#versions]
	print("Latest version: " .. latest.name)

	if isUpgrade then
		if installed == latest.name then
			print("Already up to date.")
			return
		end
		if versionLess(latest.name, installed) then
			printError("The installed version (" .. installed .. ") is newer than the latest release ("
				.. latest.name .. "). Nothing was changed.")
			return
		end
	end

	-- 3. Download every file in that version's folder
	local tree = apiGet(("%s/%s/git/trees/%s?recursive=1"):format(owner, name, latest.sha))
	if tree.truncated then
		error("This release has too many files to list in one GitHub request.", 0)
	end
	local files = {}
	for _, entry in ipairs(tree.tree or {}) do
		if entry.type == "blob" then
			files[#files + 1] = entry.path
		end
	end
	table.sort(files)
	if #files == 0 then
		error("Release " .. latest.name .. " doesn't contain any files.", 0)
	end

	local rawBase = ("https://raw.githubusercontent.com/%s/%s/"):format(owner, name)
	term.clear()
	term.setCursorPos(1,1)
	local contents = {}
	for i, rel in ipairs(files) do
		print(("[%d/%d] %s"):format(i, #files, rel))
		local url = rawBase .. encodePath(("%s/%s/%s/%s"):format(branch, releasesFolder, latest.name, rel))
		local data, err = httpGet(url, RAW_HEADERS)
		if not data then
			error(("Failed to download %s: %s"):format(rel, tostring(err)), 0)
		end
		contents[rel] = data
	end
	print("Download complete. Installing files...")
	applyFiles(installDir, contents, installed, latest.name)

	if not isUpgrade then
		-- 4. Hostname
		local hostname = promptHostname()

		-- 5. Device type
		local deviceType = promptDeviceType()

		-- 6. server_config.csv
		local ok, err = setConfigValue(fs.combine(installDir, SERVER_CONFIG), "server_hostname", hostname)
		if not ok then error(err, 0) end

		-- 7. client_config.csv
		ok, err = setConfigValue(fs.combine(installDir, CLIENT_CONFIG), "computer_type", deviceType)
		if not ok then error(err, 0) end
	end

	-- 8. Restart
	print((isUpgrade and "Upgrade" or "Installation") .. " finished. Rebooting in 3 seconds...")
	sleep(3)
	os.reboot()
end

main()
